mapper.sql:
package.id,
package.package_name AS name,
package.remark,
package.current_generation AS currentGeneration,
package.phone_count AS phoneCount,
package.version,
package.created_at AS createdAt,
package.updated_at AS updatedAt,
COALESCE(stat.unused_count, 0) AS unusedCount,
COALESCE(stat.claimed_count, 0) AS claimedCount,
COALESCE(stat.sent_count, 0) AS sentCount,
COALESCE(stat.delivered_count, 0) AS deliveredCount,
COALESCE(stat.retryable_failed_count, 0) AS retryableFailedCount,
COALESCE(stat.unregistered_count, 0) AS unregisteredCount

WHERE package.deleted_at IS NULL
AND package.package_name LIKE CONCAT('%', #{q.name}, '%')
AND package.created_at >= #{q.createdFrom}
AND package.created_at <= #{q.createdTo}
AND COALESCE(stat.unused_count, 0) > 0
AND EXISTS ( SELECT 1 FROM data_package_phone country_phone WHERE country_phone.data_package_id = package.id AND country_phone.generation = package.current_generation AND (
country_phone.country_iso2 IN
#{iso2}
OR
country_phone.country_iso2 IS NULL
) )

mapper.insert:
INSERT INTO data_package (
  package_name, remark, current_generation, phone_count, version,
  created_by, created_at, updated_at
) VALUES (
  #{packageName}, #{remark}, #{currentGeneration}, #{phoneCount}, #{version},
  #{createdBy}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT DISTINCT phone.data_package_id AS dataPackageId, phone.country_iso2 AS countryIso2 FROM data_package_phone phone INNER JOIN data_package package ON package.id = phone.data_package_id AND package.tenant_id = phone.tenant_id AND package.current_generation = phone.generation AND package.deleted_at IS NULL WHERE phone.data_package_id IN
#{packageId}
ORDER BY phone.data_package_id ASC, CASE WHEN phone.country_iso2 IS NULL THEN 1 ELSE 0 END ASC, phone.country_iso2 ASC

mapper.update:
UPDATE data_package
SET package_name = #{name},
    remark = #{remark},
    version = version + 1,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND deleted_at IS NULL
  AND version = #{version}

UPDATE data_package
SET phone_count = phone_count + #{increment},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND deleted_at IS NULL
  AND current_generation = #{generation}

UPDATE data_package
SET current_generation = #{newGeneration},
    phone_count = #{phoneCount},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND deleted_at IS NULL
  AND current_generation = #{expectedGeneration}

UPDATE data_package
SET phone_count = #{phoneCount},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND deleted_at IS NULL
  AND current_generation = #{generation}

UPDATE data_package
SET deleted_by = #{deletedBy},
    deleted_at = #{deletedAt},
    updated_at = #{deletedAt}
WHERE id = #{id}
  AND deleted_at IS NULL
